    @Nested
    class TourismTax {

        @Test
        void listsPaidReservationsStartingInTheMonthWithTaxPerGuestPerNight() {
            String csv = new TourismTaxReport(store).generate(YearMonth.of(2027, 4));

            assertEquals("""
                    Pousada Maré Alta,tourism-tax,2027-04
                    reservation,room,check_in,check_out,guests,nights,tax
                    1,201,2027-04-01,2027-04-03,1,2,9.00
                    3,301,2027-04-02,2027-04-04,1,2,9.00
                    total,18.00
                    """, csv);
        }

        @Test
        void calculatesCorrectlyForMultipleGuestsAndNights() {
            Reservation june = book(101, "2027-06-10", "2027-06-13", RatePlan.STANDARD);
            Guest multiGuest = new Guest("Ana Silva", "ana@example.com", "123.456.789-00");
            Reservation juneMulti = service.create(new NewReservation(
                    102, multiGuest, LocalDate.parse("2027-06-15"), LocalDate.parse("2027-06-17"), 3, RatePlan.NON_REFUNDABLE));
            service.confirm(june.id());
            service.confirm(juneMulti.id());

            String csv = new TourismTaxReport(store).generate(YearMonth.of(2027, 6));

            // 1 guest * 3 nights * 4.50 = 13.50
            // 3 guests * 2 nights * 4.50 = 27.00
            assertEquals("""
                    Pousada Maré Alta,tourism-tax,2027-06
                    reservation,room,check_in,check_out,guests,nights,tax
                    7,101,2027-06-10,2027-06-13,1,3,13.50
                    8,102,2027-06-15,2027-06-17,3,2,27.00
                    total,40.50
                    """, csv);
        }

        @Test
        void onlyCountsPaidReservations() {
            Reservation unpaid = book(101, "2027-07-10", "2027-07-12", RatePlan.STANDARD);

            String csv = new TourismTaxReport(store).generate(YearMonth.of(2027, 7));

            assertEquals("""
                    Pousada Maré Alta,tourism-tax,2027-07
                    reservation,room,check_in,check_out,guests,nights,tax
                    total,0.00
                    """, csv);
        }
    }

    @Nested
    class RatePlans {

        @Test
        void showsReservationsAndAmountPerPlanInTheMonth() {
            String csv = new RatePlansReport(store).generate(YearMonth.of(2027, 4));

            assertEquals("""
                    Pousada Maré Alta,rate-plans,2027-04
                    rate_plan,reservations,amount
                    STANDARD,2,1939.60
                    NON_REFUNDABLE,0,0.00
                    total,2,1939.60
                    """, csv);
        }

        @Test
        void includesCancelledNonRefundableReservations() {
            Reservation may = book(101, "2027-05-10", "2027-05-11", RatePlan.NON_REFUNDABLE);
            Reservation mayStandard = book(102, "2027-05-12", "2027-05-13", RatePlan.STANDARD);
            service.confirm(may.id());
            service.confirm(mayStandard.id());
            service.cancel(may.id());

            String csv = new RatePlansReport(store).generate(YearMonth.of(2027, 5));

            assertEquals("""
                    Pousada Maré Alta,rate-plans,2027-05
                    rate_plan,reservations,amount
                    STANDARD,1,219.40
                    NON_REFUNDABLE,1,212.42
                    total,2,431.82
                    """, csv);
        }

        @Test
        void showsZeroForPlansWithNoReservations() {
            String csv = new RatePlansReport(store).generate(YearMonth.of(2027, 6));

            assertEquals("""
                    Pousada Maré Alta,rate-plans,2027-06
                    rate_plan,reservations,amount
                    STANDARD,0,0.00
                    NON_REFUNDABLE,0,0.00
                    total,0,0.00
                    """, csv);
        }
    }
}

